# Compile dataset into JSON
dataset = []
for q_num in sorted(CH6_QUESTIONS.keys()):
    topic, q_text, opts, ref = CH6_QUESTIONS[q_num]
    correct_opt = ANS_KEY.get(q_num, "A")
    correct_text = opts.get(correct_opt, "")
    
    entry = {
        "q": q_num,
        "topic": topic,
        "question": q_text,
        "options": opts,
        "correct_option": correct_opt,
        "correct_text": correct_text,
        "textbook_ref": ref,
        "file_html": f"solutions/Q{q_num:03d}_sayeed_ch6.html",
        "title": f"Q{q_num:03d}: {topic}"
    }
    dataset.append(entry)

out_file = os.path.join(DATA_DIR, "sayeed_ch6_geochemistry.json")
with open(out_file, "w", encoding="utf-8") as f:
    json.dump(dataset, f, indent=2, ensure_ascii=False)

print(f"Successfully compiled {len(dataset)} verified questions to {out_file}")
